/// A note generated by the native scheduler and submitted to the renderer.
#[derive(Message, Clone, Debug, PartialEq)]
pub struct TidalEvent {
    pub track: u64,
    pub sound: String,
    pub note: f32,
    pub gain: f32,
    pub amp: f32,
    pub pan: f32,
    pub speed: f32,
    pub accelerate: f32,
    pub frequency: f32,
    pub sustain: f32,
    pub attack: f32,
    pub hold: f32,
    pub release: f32,
    pub begin: f32,
    pub end: f32,
    pub cut: i32,
    pub crush: f32,
    pub coarse: f32,
    pub shape: f32,
    pub distort: f32,
    pub triode: f32,
    pub cutoff: f32,
    pub resonance: f32,
    pub hpf: f32,
    pub hpq: f32,
    pub bpf: f32,
    pub bpq: f32,
    pub room: f32,
    pub dry: f32,
    pub delay: f32,
    pub delay_time: f32,
    pub delay_feedback: f32,
    pub tremolo_depth: f32,
    pub tremolo_rate: f32,
    pub ring: f32,
    pub ring_frequency: f32,
}

impl Default for TidalEvent {
    fn default() -> Self {
        Self {
            track: 0,
            sound: "sine".to_owned(),
            note: 0.0,
            gain: 1.0,
            amp: 1.0,
            pan: 0.5,
            speed: 1.0,
            accelerate: 0.0,
            frequency: 0.0,
            sustain: 0.4,
            attack: 0.005,
            hold: 0.0,
            release: 0.1,
            begin: 0.0,
            end: 1.0,
            cut: 0,
            crush: 0.0,
            coarse: 1.0,
            shape: 0.0,
            distort: 0.0,
            triode: 0.0,
            cutoff: 20_000.0,
            resonance: 0.0,
            hpf: 20.0,
            hpq: 0.0,
            bpf: 0.0,
            bpq: 0.0,
            room: 0.0,
            dry: 1.0,
            delay: 0.0,
            delay_time: 0.25,
            delay_feedback: 0.3,
            tremolo_depth: 0.0,
            tremolo_rate: 4.0,
            ring: 0.0,
            ring_frequency: 440.0,
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum NativeAudioState {
    Starting,
    Ready,
    Error,
    Stopped,
}

#[derive(Clone, Debug)]
struct AudioStatusInner {
    state: NativeAudioState,
    detail: String,
    events_received: u64,
}

/// Status of the native Rust audio device and renderer.
#[derive(Resource, Clone, Debug)]
pub struct NativeAudioStatus(Arc<RwLock<AudioStatusInner>>);

impl Default for NativeAudioStatus {
    fn default() -> Self {
        Self(Arc::new(RwLock::new(AudioStatusInner {
            state: NativeAudioState::Starting,
            detail: "Waiting to start native audio".to_owned(),
            events_received: 0,
        })))
    }
}

impl NativeAudioStatus {
    pub fn state(&self) -> NativeAudioState {
        self.0
            .read()
            .map(|status| status.state.clone())
            .unwrap_or(NativeAudioState::Error)
    }

    pub fn detail(&self) -> String {
        self.0
            .read()
            .map(|status| status.detail.clone())
            .unwrap_or_else(|_| "Native audio status lock was poisoned".to_owned())
    }

    pub fn is_ready(&self) -> bool {
        self.state() == NativeAudioState::Ready
    }

    /// Number of notes accepted by the native renderer since startup.
    pub fn events_received(&self) -> u64 {
        self.0
            .read()
            .map(|status| status.events_received)
            .unwrap_or(0)
    }

    fn set(&self, state: NativeAudioState, detail: impl Into<String>) {
        if let Ok(mut status) = self.0.write() {
            status.state = state;
            status.detail = detail.into();
        }
    }

    fn add_event(&self) {
        if let Ok(mut status) = self.0.write() {
            status.events_received = status.events_received.saturating_add(1);
        }
    }
}

#[derive(Clone, Debug)]
struct ScheduledEvent {
    at: Instant,
    event: TidalEvent,
}

/// Internal bridge from the pattern scheduler into the audio renderer.
#[derive(Resource, Clone)]
pub(crate) struct NativeAudioSender(mpsc::Sender<ScheduledEvent>);

impl NativeAudioSender {
    pub(crate) fn schedule(&self, at: Instant, event: TidalEvent) -> Result<(), String> {
        self.0
            .send(ScheduledEvent { at, event })
            .map_err(|_| "The native audio renderer is not running".to_owned())
    }
}

#[derive(Resource, Clone)]
struct NativeAudioControl(Arc<AtomicBool>);

struct ScheduledEventReceiver(Option<mpsc::Receiver<ScheduledEvent>>);
struct TidalEventReceiver(Option<mpsc::Receiver<TidalEvent>>);

pub(crate) struct NativeAudioPlugin;

impl Plugin for NativeAudioPlugin {
    fn build(&self, app: &mut App) {
        let (schedule_tx, schedule_rx) = mpsc::channel();
        let (event_tx, event_rx) = mpsc::channel();
        app.add_message::<TidalEvent>()
            .init_resource::<NativeAudioStatus>()
            .insert_resource(NativeAudioSender(schedule_tx))
            .insert_resource(TidalEventSender(event_tx))
            .add_systems(Startup, start_native_audio)
            .add_systems(Update, pump_tidal_events)
            .add_systems(Last, stop_native_audio);
        app.world_mut()
            .insert_non_send(ScheduledEventReceiver(Some(schedule_rx)));
        app.world_mut()
            .insert_non_send(TidalEventReceiver(Some(event_rx)));
    }
}

#[derive(Resource, Clone)]
struct TidalEventSender(mpsc::Sender<TidalEvent>);

fn start_native_audio(
    mut commands: Commands,
    config: Res<TidalConfig>,
    status: Res<NativeAudioStatus>,
    event_sender: Res<TidalEventSender>,
    mut scheduled: NonSendMut<ScheduledEventReceiver>,
) {
    let Some(schedule_rx) = scheduled.0.take() else {
        status.set(
            NativeAudioState::Error,
            "Native audio renderer was already started",
        );
        return;
    };
    let shutdown = Arc::new(AtomicBool::new(false));
    commands.insert_resource(NativeAudioControl(shutdown.clone()));

    let (audio_tx, audio_rx) = mpsc::channel();
    let audio_status = status.clone();
    let audio_shutdown = shutdown.clone();
    thread::Builder::new()
        .name("bevy-tidal-audio".to_owned())
        .spawn(move || run_audio_device(audio_rx, audio_status, audio_shutdown))
        .expect("failed to spawn native audio thread");

    let sample_root = absolute_path(&config.samples_path);
    let dispatcher_status = status.clone();
    let dispatcher_shutdown = shutdown;
    let bevy_events = event_sender.0.clone();
    thread::Builder::new()
        .name("bevy-tidal-sample-loader".to_owned())
        .spawn(move || {
            run_event_dispatcher(
                schedule_rx,
                audio_tx,
                bevy_events,
                sample_root,
                dispatcher_status,
                dispatcher_shutdown,
            )
        })
        .expect("failed to spawn native sample-loader thread");
}

fn stop_native_audio(
    mut exits: MessageReader<AppExit>,
    control: Option<Res<NativeAudioControl>>,
    status: Res<NativeAudioStatus>,
) {
    if exits.read().next().is_some()
        && let Some(control) = control
    {
        control.0.store(true, Ordering::SeqCst);
        status.set(NativeAudioState::Stopped, "Native audio stopped");
    }
}

fn pump_tidal_events(
    mut receiver: NonSendMut<TidalEventReceiver>,
    mut writer: MessageWriter<TidalEvent>,
) {
    let Some(receiver) = receiver.0.as_mut() else {
        return;
    };
    while let Ok(event) = receiver.try_recv() {
        writer.write(event);
    }
}

struct ScheduledTrigger {
    at: Instant,
    event: TidalEvent,
    sample: Option<Arc<SampleData>>,
}

fn run_event_dispatcher(
    rx: mpsc::Receiver<ScheduledEvent>,
    audio_tx: mpsc::Sender<ScheduledTrigger>,
    event_tx: mpsc::Sender<TidalEvent>,
    sample_root: PathBuf,
    status: NativeAudioStatus,
    shutdown: Arc<AtomicBool>,
) {
    let mut library = SampleLibrary::scan(&sample_root);
    info!(
        target: "tidal",
        "Native sample renderer indexed {} banks under {}",
        library.bank_count(),
        sample_root.display()
    );
    while !shutdown.load(Ordering::SeqCst) {
        match rx.recv_timeout(Duration::from_millis(50)) {
            Ok(scheduled) => {
                let sample = library.resolve(&scheduled.event);
                let _ = event_tx.send(scheduled.event.clone());
                if audio_tx
                    .send(ScheduledTrigger {
                        at: scheduled.at,
                        event: scheduled.event,
                        sample,
                    })
                    .is_err()
                {
                    if !shutdown.load(Ordering::SeqCst) {
                        status.set(
                            NativeAudioState::Error,
                            "Native audio stream stopped unexpectedly",
                        );
                    }
                    break;
                }
                status.add_event();
            }
            Err(mpsc::RecvTimeoutError::Timeout) => {}
            Err(mpsc::RecvTimeoutError::Disconnected) => break,
        }
    }
}

fn run_audio_device(
    rx: mpsc::Receiver<ScheduledTrigger>,
    status: NativeAudioStatus,
    shutdown: Arc<AtomicBool>,
) {
    let host = cpal::default_host();
    let Some(device) = host.default_output_device() else {
        status.set(
            NativeAudioState::Error,
            "No default audio output device was found",
        );
        return;
    };
    let supported = match device.default_output_config() {
        Ok(config) => config,
        Err(error) => {
            status.set(
                NativeAudioState::Error,
                format!("Could not read the default audio configuration: {error}"),
            );
            return;
        }
    };
    let sample_format = supported.sample_format();
    let config: StreamConfig = supported.into();
    let sample_rate = config.sample_rate as f32;
    let channels = config.channels as usize;
    let error_status = status.clone();
    let error_callback = move |error| {
        error_status.set(
            NativeAudioState::Error,
            format!("The native audio stream failed: {error}"),
        );
    };

    let stream = match sample_format {
        SampleFormat::F32 => {
            build_stream::<f32>(&device, &config, rx, sample_rate, channels, error_callback)
        }
        SampleFormat::I16 => {
            build_stream::<i16>(&device, &config, rx, sample_rate, channels, error_callback)
        }
        SampleFormat::U16 => {
            build_stream::<u16>(&device, &config, rx, sample_rate, channels, error_callback)
        }
        other => {
            status.set(
                NativeAudioState::Error,
                format!("Unsupported audio sample format: {other}"),
            );
            return;
        }
    };

    let stream = match stream {
        Ok(stream) => stream,
        Err(error) => {
            status.set(
                NativeAudioState::Error,
                format!("Could not build the native audio stream: {error}"),
            );
            return;
        }
    };
    if let Err(error) = stream.play() {
        status.set(
            NativeAudioState::Error,
            format!("Could not start native audio playback: {error}"),
        );
        return;
    }
    let device_name = device
        .description()
        .map(|description| description.to_string())
        .unwrap_or_else(|_| "default device".to_owned());
    status.set(
        NativeAudioState::Ready,
        format!("Native Rust audio ready on {device_name}"),
    );
    while !shutdown.load(Ordering::SeqCst) {
        thread::sleep(Duration::from_millis(50));
    }
}

fn build_stream<T>(
    device: &cpal::Device,
    config: &StreamConfig,
    rx: mpsc::Receiver<ScheduledTrigger>,
    sample_rate: f32,
    channels: usize,
    error_callback: impl FnMut(cpal::StreamError) + Send + 'static,
) -> Result<Stream, cpal::BuildStreamError>
where
    T: SizedSample + FromSample<f32>,
{
    let mut mixer = Mixer::new(rx, sample_rate);
    device.build_output_stream(
        config,
        move |output: &mut [T], _| write_output(output, channels, &mut mixer),
        error_callback,
        None,
    )
}

fn write_output<T>(output: &mut [T], channels: usize, mixer: &mut Mixer)
where
    T: Sample + FromSample<f32>,
{
    mixer.receive_triggers();
    for frame in output.chunks_mut(channels) {
        let [left, right] = mixer.next_frame();
        for (channel, sample) in frame.iter_mut().enumerate() {
            let value = if channel == 0 {
                left
            } else if channel == 1 {
                right
            } else {
                (left + right) * 0.5
            };
            *sample = T::from_sample(value.clamp(-1.0, 1.0));
        }
    }
}

struct Mixer {
    rx: mpsc::Receiver<ScheduledTrigger>,
    scheduled: Vec<ScheduledTrigger>,
    voices: Vec<Voice>,
    sample_rate: f32,
    room_left: Vec<f32>,
    room_right: Vec<f32>,
    room_position: usize,
    delay_left: Vec<f32>,
    delay_right: Vec<f32>,
    delay_position: usize,
}

impl Mixer {
    fn new(rx: mpsc::Receiver<ScheduledTrigger>, sample_rate: f32) -> Self {
        let room_samples = (sample_rate * 0.173).max(1.0) as usize;
        let delay_samples = (sample_rate * 2.0).max(1.0) as usize;
        Self {
            rx,
            scheduled: Vec::new(),
            voices: Vec::new(),
            sample_rate,
            room_left: vec![0.0; room_samples],
            room_right: vec![0.0; room_samples],
            room_position: 0,
            delay_left: vec![0.0; delay_samples],
            delay_right: vec![0.0; delay_samples],
            delay_position: 0,
        }
    }

    fn receive_triggers(&mut self) {
        self.scheduled.extend(self.rx.try_iter());
        let now = Instant::now();
        let mut pending = Vec::with_capacity(self.scheduled.len());
        let scheduled = std::mem::take(&mut self.scheduled);
        for trigger in scheduled {
            if trigger.at <= now {
                self.trigger(trigger);
            } else {
                pending.push(trigger);
            }
        }
        self.scheduled = pending;
    }

    fn trigger(&mut self, trigger: ScheduledTrigger) {
        if trigger.event.sound == "__panic__" {
            self.voices.clear();
            self.scheduled.clear();
            self.room_left.fill(0.0);
            self.room_right.fill(0.0);
            self.delay_left.fill(0.0);
            self.delay_right.fill(0.0);
            return;
        }
        if trigger.event.cut != 0 {
            self.voices.retain(|voice| voice.cut != trigger.event.cut);
        }
        if self.voices.len() >= 128 {
            self.voices.remove(0);
        }
        self.voices
            .push(Voice::new(trigger.event, trigger.sample, self.sample_rate));
    }

    fn next_frame(&mut self) -> [f32; 2] {
        let mut dry = [0.0, 0.0];
        let mut room_send = [0.0, 0.0];
        let mut delay_send = [0.0, 0.0];
        let mut delay_time = 0.25;
        let mut delay_feedback = 0.3;
        for voice in &mut self.voices {
            let sample = voice.next(self.sample_rate);
            dry[0] += sample[0] * voice.dry;
            dry[1] += sample[1] * voice.dry;
            room_send[0] += sample[0] * voice.room;
            room_send[1] += sample[1] * voice.room;
            delay_send[0] += sample[0] * voice.delay;
            delay_send[1] += sample[1] * voice.delay;
            if voice.delay > 0.0 {
                delay_time = voice.delay_time;
                delay_feedback = voice.delay_feedback;
            }
        }
        self.voices.retain(|voice| voice.alive);

        let delayed = [
            self.room_left[self.room_position],
            self.room_right[self.room_position],
        ];
        self.room_left[self.room_position] = room_send[0] + delayed[1] * 0.55;
        self.room_right[self.room_position] = room_send[1] + delayed[0] * 0.55;
        self.room_position = (self.room_position + 1) % self.room_left.len();

        let delay_offset =
            (delay_time * self.sample_rate).clamp(1.0, self.delay_left.len() as f32 - 1.0) as usize;
        let delay_read =
            (self.delay_position + self.delay_left.len() - delay_offset) % self.delay_left.len();
        let echo = [self.delay_left[delay_read], self.delay_right[delay_read]];
        self.delay_left[self.delay_position] =
            delay_send[0] + echo[0] * delay_feedback.clamp(0.0, 0.98);
        self.delay_right[self.delay_position] =
            delay_send[1] + echo[1] * delay_feedback.clamp(0.0, 0.98);
        self.delay_position = (self.delay_position + 1) % self.delay_left.len();
        [
            dry[0] + delayed[0] * 0.35 + echo[0],
            dry[1] + delayed[1] * 0.35 + echo[1],
        ]
    }
}

enum VoiceKind {
    Sample {
        data: Arc<SampleData>,
        position: f64,
        step: f64,
        end: f64,
    },
    Kick,
    Snare,
    Hat {
        previous_noise: f32,
    },
    Clap,
    Tone {
        frequency: f32,
    },
    Saw {
        frequency: f32,
    },
    Square {
        frequency: f32,
    },
    Noise,
    Fm {
        frequency: f32,
    },
    Bell {
        frequency: f32,
    },
}

struct Voice {
    kind: VoiceKind,
    age: u64,
    max_age: u64,
    phase: f32,
    gain: f32,
    pan: f32,
    cut: i32,
    crush: f32,
    coarse: u32,
    coarse_counter: u32,
    coarse_value: f32,
    shape: f32,
    distort: f32,
    triode: f32,
    cutoff: f32,
    resonance: f32,
    filter_one: f32,
    filter_two: f32,
    hpf: f32,
    hpq: f32,
    hpf_state: f32,
    bpf: f32,
    bpq: f32,
    bpf_low: f32,
    bpf_state: f32,
    accelerate: f32,
    attack: f32,
    release: f32,
    tremolo_depth: f32,
    tremolo_rate: f32,
    ring: f32,
    ring_frequency: f32,
    dry: f32,
    room: f32,
    delay: f32,
    delay_time: f32,
    delay_feedback: f32,
    rng: u32,
    alive: bool,
}

impl Voice {
    fn new(event: TidalEvent, sample: Option<Arc<SampleData>>, output_rate: f32) -> Self {
        let sustain = event.sustain.max(0.05);
        let sound = event.sound.to_ascii_lowercase();
        let frequency = if event.frequency > 0.0 {
            event.frequency
        } else {
            261.625_55 * 2.0_f32.powf(event.note / 12.0)
        };
        let (kind, seconds) = if let Some(data) = sample {
            let begin = event.begin.clamp(0.0, 1.0);
            let end = event.end.clamp(begin + f32::EPSILON, 1.0);
            let last_frame = data.frames.len().saturating_sub(1) as f64;
            let begin_frame = f64::from(begin) * last_frame;
            let end_frame = f64::from(end) * last_frame;
            let direction = if event.speed < 0.0 { -1.0 } else { 1.0 };
            let step = (data.sample_rate as f64 / output_rate as f64)
                * event.speed.abs().max(0.01) as f64
                * direction;
            let position = if step >= 0.0 { begin_frame } else { end_frame };
            let sample_end = if step >= 0.0 { end_frame } else { begin_frame };
            let seconds = ((end_frame - begin_frame).abs() / step.abs() / output_rate as f64)
                .max(1.0 / output_rate as f64) as f32;
            (
                VoiceKind::Sample {
                    data,
                    position,
                    step,
                    end: sample_end,
                },
                seconds,
            )
        } else if matches!(
            sound.as_str(),
            "bd" | "kick" | "superkick" | "super808" | "soskick"
        ) {
            (VoiceKind::Kick, sustain.max(0.3))
        } else if matches!(
            sound.as_str(),
            "sd" | "sn" | "snare" | "supersnare" | "sossnare"
        ) {
            (VoiceKind::Snare, sustain.max(0.22))
        } else if matches!(
            sound.as_str(),
            "hh" | "hc" | "ho" | "hat" | "superhat" | "soshats"
        ) {
            (
                VoiceKind::Hat {
                    previous_noise: 0.0,
                },
                sustain.min(0.35),
            )
        } else if matches!(sound.as_str(), "cp" | "clap" | "superclap") {
            (VoiceKind::Clap, sustain.max(0.3))
        } else if matches!(
            sound.as_str(),
            "supersaw"
                | "superhoover"
                | "superzow"
                | "supertron"
                | "superreese"
                | "supersiren"
                | "supergrind"
        ) {
            (
                VoiceKind::Saw { frequency },
                sustain + event.hold + event.release,
            )
        } else if matches!(
            sound.as_str(),
            "supersquare" | "superpwm" | "superchip" | "supercomparator"
        ) {
            (
                VoiceKind::Square { frequency },
                sustain + event.hold + event.release,
            )
        } else if matches!(sound.as_str(), "supernoise" | "superstatic") {
            (VoiceKind::Noise, sustain + event.hold + event.release)
        } else if sound == "superfm" {
            (
                VoiceKind::Fm { frequency },
                sustain + event.hold + event.release,
            )
        } else if matches!(
            sound.as_str(),
            "supergong"
                | "supervibe"
                | "superfork"
                | "supermandolin"
                | "superpiano"
                | "superhammond"
        ) {
            (
                VoiceKind::Bell { frequency },
                sustain + event.hold + event.release,
            )
        } else {
            (
                VoiceKind::Tone { frequency },
                sustain.max(0.2) + event.hold + event.release,
            )
        };
        Self {
            kind,
            age: 0,
            max_age: (seconds * output_rate).max(1.0) as u64,
            phase: 0.0,
            gain: (event.gain * event.amp).clamp(0.0, 4.0),
            pan: event.pan.clamp(0.0, 1.0),
            cut: event.cut,
            crush: event.crush.clamp(0.0, 16.0),
            coarse: event.coarse.round().clamp(1.0, 128.0) as u32,
            coarse_counter: 0,
            coarse_value: 0.0,
            shape: event.shape.clamp(0.0, 1.0),
            distort: event.distort.clamp(0.0, 1.0),
            triode: event.triode.clamp(0.0, 1.0),
            cutoff: event.cutoff.clamp(20.0, output_rate * 0.45),
            resonance: event.resonance.clamp(0.0, 1.0),
            filter_one: 0.0,
            filter_two: 0.0,
            hpf: event.hpf.clamp(20.0, output_rate * 0.45),
            hpq: event.hpq.clamp(0.0, 1.0),
            hpf_state: 0.0,
            bpf: event.bpf.clamp(0.0, output_rate * 0.45),
            bpq: event.bpq.clamp(0.0, 1.0),
            bpf_low: 0.0,
            bpf_state: 0.0,
            accelerate: event.accelerate,
            attack: event.attack.max(0.0),
            release: event.release.max(0.0),
            tremolo_depth: event.tremolo_depth.clamp(0.0, 1.0),
            tremolo_rate: event.tremolo_rate.max(0.0),
            ring: event.ring.clamp(0.0, 1.0),
            ring_frequency: event.ring_frequency.max(0.0),
            dry: event.dry.clamp(0.0, 1.0),
            room: event.room.clamp(0.0, 1.0),
            delay: event.delay.clamp(0.0, 1.0),
            delay_time: event.delay_time.clamp(0.001, 2.0),
            delay_feedback: event.delay_feedback.clamp(0.0, 0.98),
            rng: 0xA341_316C_u32 ^ event.note.to_bits(),
            alive: true,
        }
    }

    fn next(&mut self, sample_rate: f32) -> [f32; 2] {
        if self.age >= self.max_age {
            self.alive = false;
            return [0.0, 0.0];
        }
        let time = self.age as f32 / sample_rate;
        let progress = self.age as f32 / self.max_age as f32;
        let pitch_glide = 2.0_f32.powf(self.accelerate * time);
        let mut mono = match &mut self.kind {
            VoiceKind::Sample {
                data,
                position,
                step,
                end,
            } => {
                let finished = if *step >= 0.0 {
                    *position >= *end
                } else {
                    *position <= *end
                };
                let index = *position as usize;
                if finished || index + 1 >= data.frames.len() {
                    self.alive = false;
                    0.0
                } else {
                    let fraction = (*position - index as f64) as f32;
                    let current = (data.frames[index][0] + data.frames[index][1]) * 0.5;
                    let next = (data.frames[index + 1][0] + data.frames[index + 1][1]) * 0.5;
                    *position += *step * f64::from(pitch_glide);
                    current + (next - current) * fraction
                }
            }
            VoiceKind::Kick => {
                let frequency = 45.0 + 115.0 * (-time * 28.0).exp();
                self.phase = (self.phase + TAU * frequency / sample_rate) % TAU;
                self.phase.sin() * (-time * 10.0).exp()
            }
            VoiceKind::Snare => {
                let noise = next_noise(&mut self.rng);
                let tone = (TAU * 185.0 * time).sin() * (-time * 18.0).exp();
                noise * (-time * 13.0).exp() * 0.75 + tone * 0.25
            }
            VoiceKind::Hat { previous_noise } => {
                let noise = next_noise(&mut self.rng);
                let high_passed = noise - *previous_noise * 0.94;
                *previous_noise = noise;
                high_passed * (-time * 35.0).exp() * 0.55
            }
            VoiceKind::Clap => {
                let noise = next_noise(&mut self.rng);
                let burst = ((time * 55.0 * PI).sin().max(0.0) + 0.2).min(1.0);
                noise * burst * (-time * 12.0).exp() * 0.65
            }
            VoiceKind::Tone { frequency } => {
                self.phase = (self.phase + TAU * *frequency * pitch_glide / sample_rate) % TAU;
                (self.phase.sin() * 0.75 + (self.phase * 2.0).sin() * 0.25) * 0.45
            }
            VoiceKind::Saw { frequency } => {
                self.phase = (self.phase + TAU * *frequency * pitch_glide / sample_rate) % TAU;
                (self.phase / PI - 1.0) * 0.35
            }
            VoiceKind::Square { frequency } => {
                self.phase = (self.phase + TAU * *frequency * pitch_glide / sample_rate) % TAU;
                if self.phase < PI { 0.3 } else { -0.3 }
            }
            VoiceKind::Noise => next_noise(&mut self.rng) * 0.3,
            VoiceKind::Fm { frequency } => {
                self.phase = (self.phase + TAU * *frequency * pitch_glide / sample_rate) % TAU;
                (self.phase + (self.phase * 2.01).sin() * 3.0).sin() * 0.4
            }
            VoiceKind::Bell { frequency } => {
                self.phase = (self.phase + TAU * *frequency * pitch_glide / sample_rate) % TAU;
                (self.phase.sin() * 0.55
                    + (self.phase * 2.71).sin() * 0.25
                    + (self.phase * 5.82).sin() * 0.2)
                    * (-time * 3.5).exp()
                    * 0.5
            }
        };

        if self.coarse > 1 {
            if self.coarse_counter == 0 {
                self.coarse_value = mono;
            }
            mono = self.coarse_value;
            self.coarse_counter = (self.coarse_counter + 1) % self.coarse;
        }
        if self.shape > 0.0 {
            let drive = 1.0 + self.shape * 12.0;
            mono = (mono * drive).tanh() / drive.tanh();
        }
        if self.crush >= 1.0 {
            let levels = 2.0_f32.powf(self.crush).max(2.0);
            mono = (mono * levels).round() / levels;
        }
        if self.distort > 0.0 {
            let drive = 1.0 + self.distort * 40.0;
            mono = (mono * drive).tanh();
        }
        if self.triode > 0.0 {
            let biased = mono + self.triode * 0.35;
            mono = biased.tanh() - (self.triode * 0.35).tanh();
        }
        let filter_alpha = 1.0 - (-TAU * self.cutoff / sample_rate).exp();
        self.filter_one += filter_alpha * (mono - self.filter_one);
        self.filter_two += filter_alpha * (self.filter_one - self.filter_two);
        mono = self.filter_two + (self.filter_one - self.filter_two) * self.resonance * 0.65;

        if self.hpf > 20.0 {
            let alpha = 1.0 - (-TAU * self.hpf / sample_rate).exp();
            self.hpf_state += alpha * (mono - self.hpf_state);
            mono = (mono - self.hpf_state) * (1.0 + self.hpq * 0.75);
        }
        if self.bpf > 0.0 {
            let coefficient = (2.0 * (PI * self.bpf / sample_rate).sin()).clamp(0.0, 0.99);
            self.bpf_low += coefficient * self.bpf_state;
            let high = mono - self.bpf_low - (1.0 - self.bpq * 0.85) * self.bpf_state;
            self.bpf_state += coefficient * high;
            mono = self.bpf_state;
        }

        if self.tremolo_depth > 0.0 {
            let modulation = 0.5 + 0.5 * (TAU * self.tremolo_rate * time).sin();
            mono *= 1.0 - self.tremolo_depth + self.tremolo_depth * modulation;
        }
        if self.ring > 0.0 {
            let ring = (TAU * self.ring_frequency * time).sin();
            mono *= 1.0 - self.ring + self.ring * ring;
        }

        let attack_envelope = if self.attack > 0.0 {
            (time / self.attack).clamp(0.0, 1.0)
        } else {
            1.0
        };
        let remaining = (self.max_age - self.age) as f32 / sample_rate;
        let release_envelope = if self.release > 0.0 {
            (remaining / self.release).clamp(0.0, 1.0)
        } else {
            (1.0 - progress).clamp(0.0, 1.0)
        };
        mono *= attack_envelope * release_envelope;

        mono *= self.gain;
        let angle = self.pan * FRAC_PI_2;
        self.age += 1;
        [mono * angle.cos(), mono * angle.sin()]
    }
}

fn next_noise(state: &mut u32) -> f32 {
    let mut value = *state;
    value ^= value << 13;
    value ^= value >> 17;
    value ^= value << 5;
    *state = value;
    (value as f32 / u32::MAX as f32) * 2.0 - 1.0
}

struct SampleData {
    sample_rate: u32,
    frames: Vec<[f32; 2]>,
}

struct SampleLibrary {
    banks: HashMap<String, Vec<PathBuf>>,
    cache: HashMap<PathBuf, Arc<SampleData>>,
}

impl SampleLibrary {
    fn scan(root: &Path) -> Self {
        let mut banks: HashMap<String, Vec<PathBuf>> = HashMap::new();
        scan_sample_paths(root, &mut banks);
        for paths in banks.values_mut() {
            paths.sort();
        }
        Self {
            banks,
            cache: HashMap::new(),
        }
    }

    fn bank_count(&self) -> usize {
        self.banks.len()
    }

    fn resolve(&mut self, event: &TidalEvent) -> Option<Arc<SampleData>> {
        let requested = event.sound.to_ascii_lowercase();
        let alias = match requested.as_str() {
            "bd" => "kick",
            "sd" | "sn" => "snare",
            "cp" => "clap",
            "hh" | "hc" | "ho" => "hi",
            _ => requested.as_str(),
        };
        let paths = self.banks.get(alias)?;
        let index = (event.note.round().max(0.0) as usize) % paths.len();
        let path = paths[index].clone();
        if let Some(sample) = self.cache.get(&path) {
            return Some(sample.clone());
        }
        match load_wav(&path) {
            Ok(sample) => {
                let sample = Arc::new(sample);
                self.cache.insert(path, sample.clone());
                Some(sample)
            }
            Err(error) => {
                warn!(target: "tidal", "Could not load sample {}: {error}", path.display());
                None
            }
        }
    }
}

fn scan_sample_paths(root: &Path, banks: &mut HashMap<String, Vec<PathBuf>>) {
    let Ok(entries) = std::fs::read_dir(root) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            scan_sample_paths(&path, banks);
        } else if path
            .extension()
            .and_then(|extension| extension.to_str())
            .is_some_and(|extension| extension.eq_ignore_ascii_case("wav"))
            && let Some(bank) = path
                .parent()
                .and_then(Path::file_name)
                .and_then(|name| name.to_str())
        {
            banks
                .entry(bank.to_ascii_lowercase())
                .or_default()
                .push(path);
        }
    }
}

fn load_wav(path: &Path) -> Result<SampleData, hound::Error> {
    let mut reader = hound::WavReader::open(path)?;
    let spec = reader.spec();
    let channels = spec.channels.max(1) as usize;
    let raw: Vec<f32> = match spec.sample_format {
        hound::SampleFormat::Float => reader.samples::<f32>().collect::<Result<_, _>>()?,
        hound::SampleFormat::Int if spec.bits_per_sample <= 8 => reader
            .samples::<i8>()
            .map(|sample| sample.map(|sample| sample as f32 / i8::MAX as f32))
            .collect::<Result<_, _>>()?,
        hound::SampleFormat::Int if spec.bits_per_sample <= 16 => reader
            .samples::<i16>()
            .map(|sample| sample.map(|sample| sample as f32 / i16::MAX as f32))
            .collect::<Result<_, _>>()?,
        hound::SampleFormat::Int => {
            let maximum = ((1_i64 << (spec.bits_per_sample - 1)) - 1) as f32;
            reader
                .samples::<i32>()
                .map(|sample| sample.map(|sample| sample as f32 / maximum))
                .collect::<Result<_, _>>()?
        }
    };
    let frames = raw
        .chunks(channels)
        .map(|frame| {
            let left = frame.first().copied().unwrap_or(0.0);
            let right = frame.get(1).copied().unwrap_or(left);
            [left, right]
        })
        .collect();
    Ok(SampleData {
        sample_rate: spec.sample_rate,
        frames,
    })
}

fn absolute_path(path: &Path) -> PathBuf {
    if path.is_absolute() {
        path.to_owned()
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(path)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn native_event_has_safe_audio_defaults() {
        let event = TidalEvent::default();
        assert_eq!(event.sound, "sine");
        assert_eq!(event.gain, 1.0);
        assert_eq!(event.cutoff, 20_000.0);
    }

    #[test]
    fn built_in_voice_and_effects_produce_finite_audio() {
        let event = TidalEvent {
            sound: "bd".to_owned(),
            crush: 4.0,
            shape: 0.5,
            cutoff: 2_000.0,
            resonance: 0.3,
            room: 0.4,
            ..TidalEvent::default()
        };
        let mut voice = Voice::new(event, None, 48_000.0);
        for _ in 0..1_000 {
            let frame = voice.next(48_000.0);
            assert!(frame[0].is_finite());
            assert!(frame[1].is_finite());
        }
    }

    #[test]
    fn documented_synth_families_and_controls_render_without_sidecars() {
        for sound in [
            "superkick",
            "supersnare",
            "superhat",
            "superclap",
            "supersaw",
            "supersquare",
            "supernoise",
            "superfm",
            "supergong",
            "superpiano",
        ] {
            let event = TidalEvent {
                sound: sound.to_owned(),
                frequency: 220.0,
                amp: 0.7,
                attack: 0.01,
                release: 0.2,
                coarse: 3.0,
                distort: 0.2,
                triode: 0.1,
                hpf: 80.0,
                bpf: 1_200.0,
                tremolo_depth: 0.2,
                ring: 0.1,
                delay: 0.2,
                ..TidalEvent::default()
            };
            let mut voice = Voice::new(event, None, 48_000.0);
            for _ in 0..256 {
                let frame = voice.next(48_000.0);
                assert!(frame.into_iter().all(f32::is_finite), "{sound}");
            }
        }
    }
}
